const LEVEL_INDEX = new Map<string, Mir4LevelRow>();
for (const row of MIR4_LEVEL_ROWS) LEVEL_INDEX.set(row[0] + ':' + row[1], row);

/** The source level row for (classId, level), or null outside the 1..250 table. */
export function mir4LevelRow(classId: number, level: number): Mir4LevelRow | null {
  return LEVEL_INDEX.get(classId + ':' + level) ?? null;
}
